package bookstore

// Cost returns the cost, in cents, of the books in the basket after
// applying the largest possible discount.
//
// Each entry of books is the title (1-5) of a book in the series. Copies
// are grouped into sets of distinct titles, and a group of n different
// titles costs n copies at $8 with the discount for n books (100%, 95%,
// 90%, 80% or 75% for n = 1..5), i.e. 800, 1520, 2160, 2560 or 3000
// cents per group.
func Cost(books []int) int {
	var counts [5]int
	for _, book := range books {
		counts[book-1]++
	}

	// Split the basket into "layers": layer i contains one copy of every
	// title that has at least i copies in the basket. Each layer is a
	// group of distinct titles, so the layers form a valid grouping.
	var groups [6]int // groups[n] = number of groups of size n
	maxCount := 0
	for _, c := range counts {
		if c > maxCount {
			maxCount = c
		}
	}
	for level := 1; level <= maxCount; level++ {
		size := 0
		for _, c := range counts {
			if c >= level {
				size++
			}
		}
		groups[size]++
	}

	// A group of five plus a group of three costs 3000+2160 = 5160, while
	// two groups of four cost 2560+2560 = 5120, so whenever both a group
	// of five and a group of three are present, trade them for two groups
	// of four.
	trades := groups[5]
	if groups[3] < trades {
		trades = groups[3]
	}
	groups[5] -= trades
	groups[3] -= trades
	groups[4] += 2*trades

	groupPrice := [6]int{0, 800, 1520, 2160, 2560, 3000}
	total := 0
	for size := 1; size <= 5; size++ {
		total += groups[size] * groupPrice[size]
	}
	return total
}

package main

import (
	"fmt"
	"math/rand"
	"sort"
)

var groupPrice = [6]int{0, 800, 1520, 2160, 2560, 3000}

// solution: layer decomposition + (5,3)->(4,4) trades, as in book_store.go
func solution(counts [5]int) int {
	var groups [6]int
	maxCount := 0
	for _, c := range counts {
		if c > maxCount {
			maxCount = c
		}
	}
	for level := 1; level <= maxCount; level++ {
		size := 0
		for _, c := range counts {
			if c >= level {
				size++
			}
		}
		groups[size]++
	}
	trades := groups[5]
	if groups[3] < trades {
		trades = groups[3]
	}
	groups[5] -= trades
	groups[3] -= trades
	groups[4] += 2 * trades
	total := 0
	for size := 1; size <= 5; size++ {
		total += groups[size] * groupPrice[size]
	}
	return total
}

// brute force: DP over count vectors, trying every possible group
var memo = map[[5]int]int{}

func brute(counts [5]int) int {
	sort.Ints(counts[:])
	if v, ok := memo[counts]; ok {
		return v
	}
	best := 0
	any := false
	for mask := 1; mask < 32; mask++ {
		n := 0
		ok := true
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				if counts[i] == 0 {
					ok = false
					break
				}
				n++
			}
		}
		if !ok {
			continue
		}
		next := counts
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				next[i]--
			}
		}
		sort.Ints(next[:])
		cost := groupPrice[n] + brute(next)
		if !any || cost < best {
			best = cost
			any = true
		}
	}
	memo[counts] = best
	return best
}

func main() {
	// exhaustive: every count vector with each count in 0..4
	bad := 0
	for c1 := 0; c1 <= 4; c1++ {
		for c2 := 0; c2 <= 4; c2++ {
			for c3 := 0; c3 <= 4; c3++ {
				for c4 := 0; c4 <= 4; c4++ {
					for c5 := 0; c5 <= 4; c5++ {
						counts := [5]int{c1, c2, c3, c4, c5}
						if s, b := solution(counts), brute(counts); s != b {
							bad++
							if bad < 10 {
								fmt.Printf("MISMATCH %v: solution=%d brute=%d\n", counts, s, b)
							}
						}
					}
				}
			}
		}
	}

	// random larger baskets
	rng := rand.New(rand.NewSource(1))
	for i := 0; i < 2000; i++ {
		var counts [5]int
		for j := 0; j < 5; j++ {
			counts[j] = rng.Intn(9)
		}
		if s, b := solution(counts), brute(counts); s != b {
			bad++
			if bad < 20 {
				fmt.Printf("MISMATCH %v: solution=%d brute=%d\n", counts, s, b)
			}
		}
	}

	if bad == 0 {
		fmt.Println("OK: solution matches brute force on all checked baskets")
	} else {
		fmt.Printf("FAILED: %d mismatches\n", bad)
	}
}

