package bookstore

// Temporary verification file: compares Cost against a brute-force DP over
// all possible groupings. Deleted after verification.

import (
	"math/rand"
	"sort"
	"testing"
)

var groupPrice = [6]int{0, 800, 1520, 2160, 2560, 3000}

var memo = map[[5]int]int{}

func bruteForce(counts [5]int) int {
	sort.Ints(counts[:])
	if v, ok := memo[counts]; ok {
		return v
	}
	best := 0
	any := false
	for mask := 1; mask < 32; mask++ {
		n := 0
		ok := true
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				if counts[i] == 0 {
					ok = false
					break
				}
				n++
			}
		}
		if !ok {
			continue
		}
		next := counts
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				next[i]--
			}
		}
		sort.Ints(next[:])
		cost := groupPrice[n] + bruteForce(next)
		if !any || cost < best {
			best = cost
			any = true
		}
	}
	memo[counts] = best
	return best
}

func basketFromCounts(counts [5]int) []int {
	var books []int
	for title, c := range counts {
		for i := 0; i < c; i++ {
			books = append(books, title+1)
		}
	}
	return books
}

func TestVerifyAgainstBruteForce(t *testing.T) {
	// exhaustive: every count vector with each count in 0..4 (3125 baskets)
	for c1 := 0; c1 <= 4; c1++ {
		for c2 := 0; c2 <= 4; c2++ {
			for c3 := 0; c3 <= 4; c3++ {
				for c4 := 0; c4 <= 4; c4++ {
					for c5 := 0; c5 <= 4; c5++ {
						counts := [5]int{c1, c2, c3, c4, c5}
						books := basketFromCounts(counts)
						if got, want := Cost(books), bruteForce(counts); got != want {
							t.Fatalf("counts %v: Cost=%d brute=%d", counts, got, want)
						}
					}
				}
			}
		}
	}
	// random larger baskets (counts up to 8 each)
	rng := rand.New(rand.NewSource(1))
	for i := 0; i < 2000; i++ {
		var counts [5]int
		for j := 0; j < 5; j++ {
			counts[j] = rng.Intn(9)
		}
		books := basketFromCounts(counts)
		if got, want := Cost(books), bruteForce(counts); got != want {
			t.Fatalf("counts %v: Cost=%d brute=%d", counts, got, want)
		}
	}
}
